"""伤害计算。"""

from arena.model import Combatant


def effective_armor(defender: Combatant, attacker: Combatant) -> int:
    """有效护甲。"""
    return defender.armor - attacker.pierce


def actual_atk(attacker: Combatant) -> int:
    return attacker.atk + 10 * attacker.attack_up_stacks


def base_damage(attacker: Combatant, mult_pct: int) -> int:
    """基础伤害。"""
    return round(actual_atk(attacker) * mult_pct / 100)


def resolve(attacker: Combatant, defender: Combatant, mult_pct: int) -> int:
    """结算一次普通攻击或技能。"""
    dmg = base_damage(attacker, mult_pct)
    armor = effective_armor(defender, attacker)
    if attacker.crit:
        dmg = dmg * 2 - armor
    else:
        dmg = dmg - armor
    return max(1, dmg)

"""增益与减益。"""

from arena.model import Combatant

MAX_ATTACK_UP_STACKS = 3


def apply_attack_up(target: Combatant, turns: int = 2) -> None:
    """施加一层攻击增益。"""
    target.attack_up_stacks += 1
    target.attack_up_turns = turns


def tick_buffs(target: Combatant) -> None:
    """回合结束时衰减增益。"""
    if target.attack_up_turns > 0:
        target.attack_up_turns -= 1
        if target.attack_up_turns == 0:
            target.attack_up_stacks = 0

"""回合循环。"""

from arena import effects, rules
from arena.model import Combatant


def turn_order(combatants: list[Combatant]) -> list[Combatant]:
    """按速度排序，存活者参与。"""
    alive = [c for c in combatants if c.alive]
    return sorted(alive, key=lambda c: (-c.speed, c.name))


def run_battle(
    hero: Combatant,
    enemy: Combatant,
    mult_pct: int = 100,
    max_rounds: int = 20,
) -> dict:
    participants = [hero, enemy]
    log: list[dict] = []
    rounds = 0

    while rounds < max_rounds:
        rounds += 1
        acted = False
        for actor in turn_order(participants):
            if not actor.alive:
                continue
            target = next((c for c in participants if c is not actor and c.alive), None)
            if target is None:
                break
            acted = True
            damage = rules.resolve(actor, target, mult_pct)
            target.hp -= damage
            log.append(
                {
                    "round": rounds,
                    "actor": actor.id,
                    "target": target.id,
                    "damage": damage,
                    "target_hp": max(0, target.hp),
                }
            )
        for c in participants:
            if c.alive:
                effects.tick_buffs(c)
        if not acted:
            break
        if not hero.alive or not enemy.alive:
            break

    winner = None
    if hero.alive and not enemy.alive:
        winner = hero.id
    elif enemy.alive and not hero.alive:
        winner = enemy.id

    return {
        "winner": winner,
        "rounds": rounds,
        "log": log,
        "hero_hp": max(0, hero.hp),
        "enemy_hp": max(0, enemy.hp),
    }

